"""Canonical identities for claims and their generated bytes."""

from __future__ import annotations

import hashlib
import json
import os
from collections.abc import Mapping

from . import core, recipe as recipe_module


def _claim_format(recipe: Mapping) -> int:
    """Return the declared claim format (one when omitted)."""
    return recipe.get("claim", {}).get("format", 1)


def _preimage_recipe(recipe: Mapping) -> dict:
    """Return the recipe content that participates in the root."""
    result = dict(recipe)
    if _claim_format(recipe) >= 3:
        result["step"] = [
            {key: value for key, value in step.items()
             if step.get("kind") != "produce" or key not in core.GUIDANCE_KEYS}
            for step in recipe.get("step", [])
        ]
    return result


def _parts(recipe: Mapping, directory: str | os.PathLike[str]) -> dict[str, str]:
    """Build the string map named by the canonical root serialization."""
    parts = {
        "digest": core.DIGEST,
        "recipe": json.dumps(_preimage_recipe(recipe), sort_keys=True),
    }
    for name in recipe_module._inputs(recipe, directory):
        parts["input:" + name] = core._hash_file(core._safe(directory, name))
    for step in recipe_module._steps(recipe):
        default_class = "generated" if step["kind"] == "produce" else "pinned"
        if step.get("class", default_class) != "generated":
            name = step["output"]
            parts["pinned:" + name] = core._hash_file(core._safe(directory, name))
    return parts


def root(recipe: Mapping, directory: str | os.PathLike[str]) -> str:
    """Hash the canonical claim preimage."""
    encoded = json.dumps(_parts(recipe, directory), sort_keys=True).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def build_digest(directory: str | os.PathLike[str]) -> str:
    """Hash the present, locally generated output bytes of a claim."""
    claim_recipe = recipe_module.load_recipe(directory)
    generated = []
    for step in recipe_module.produces(claim_recipe):
        if step.get("class", "generated") != "generated" or "from" in step:
            continue
        name = step["output"]
        path = core._safe(directory, name)
        if os.path.lexists(path):
            generated.append((name, core._hash_file(path)))
    encoded = json.dumps(sorted(generated), sort_keys=True).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()
